package com.logatron.investigation.infrastructure;
import com.logatron.auth.application.EffectiveScope;import com.logatron.investigation.application.InvestigationPorts.LogEvidencePort;import com.logatron.investigation.domain.InvestigationModels.*;import com.logatron.logquery.application.LogQueryService;import com.logatron.logquery.domain.LogSearchCriteria;import com.logatron.logquery.web.LogQueryDtos.LogRow;import org.springframework.stereotype.Component;import java.util.*;
@Component public class AuthorizedLogEvidenceAdapter implements LogEvidencePort {private final LogQueryService logs;public AuthorizedLogEvidenceAdapter(LogQueryService logs){this.logs=logs;}public List<LogRow> query(EffectiveScope scope,InvestigationQuery q){String trace=null,request=null,correlation=null,transaction=null,order=null,auction=null;switch(q.identifierType()){case TRACE_ID->trace=q.identifierValue();case REQUEST_ID->request=q.identifierValue();case CORRELATION_ID->correlation=q.identifierValue();case TRANSACTION_ID->transaction=q.identifierValue();case ORDER_TOKEN->order=q.identifierValue();case AUCTION_ID->auction=q.identifierValue();case SCOPE->{}}
  var criteria=new LogSearchCriteria(q.projectId(),q.environmentId(),null,null,null,q.from(),q.to(),trace,null,request,correlation,transaction,order,auction,null,null,500,null).normalize(java.time.Clock.systemUTC());return logs.execute(scope,criteria).items();}}

